from collections import deque
def longestSubarray(nums, limit):
    mx, mn = deque(), deque()
    left = best = 0
    for right, x in enumerate(nums):
        while mx and nums[mx[-1]] <= x:
            mx.pop()
        mx.append(right)
        while mn and nums[mn[-1]] >= x:
            mn.pop()
        mn.append(right)
        while nums[mx[0]] - nums[mn[0]] > limit:
            left += 1
            if mx[0] < left:
                mx.popleft()
            if mn[0] < left:
                mn.popleft()
        best = max(best, right - left + 1)
    return best

