def longestSubarray(nums, limit):
    best = 0
    for i in range(len(nums)):
        lo = hi = nums[i]
        for j in range(i, len(nums)):
            lo = min(lo, nums[j])
            hi = max(hi, nums[j])
            if hi - lo > limit:
                break
            best = max(best, j - i + 1)
    return best

